#define STRICT_LIBRARY
#include "../four/strict.cpp"
// Exact target reachability (DTD0), one-sided materials and KQvKP. Three target bits: KQvK, KRvK, KvKP (relative to canonical KQvKP).
int main(){init();setup();auto cwd=filesystem::current_path();filesystem::current_path("../four");load();loadD();filesystem::current_path(cwd);vector<vector<uint8_t>> bits(ts.size());for(int id=0;id<(int)ts.size();id++){auto&t=ts[id];if(t.c[3]&&t.n==4)continue;bits[id].resize(t.sz);vector<vector<U>> bins(128);int own=t.name=="KQvK"?1:t.name=="KRvK"?2:0;for(U a=0;a<(U)t.sz;a++)if(pc(t.v[a])==0&&t.v[a]!=INV){bits[id][a]=own;if(ds[id][a]!=INF&&ds[id][a]>0&&t.v[a]!=DEAD)bins[ds[id][a]].push_back(a);}for(int d=1;d<128;d++)for(U a:bins[d]){Pos p=dec(t,a);moves(t,p,[&](Move m,Pos v){auto[j,q]=child(t,p,m,v);U b=enc(ts[j],q);if(pc(ts[j].v[b])!=0||ds[j][b]!=d-1||bits[j].empty())return;bits[id][a]|=bits[j][b];});}if(t.n==4){long long c[2][2]={};for(U a=0;a<(U)t.sz;a++)if(pc(t.v[a])==0&&t.v[a]!=INV)for(int k=0;k<2;k++)if(bits[id][a]&(1<<k))c[dec(t,a).turn][k]++;cout<<t.name<<'\t'<<c[0][0]<<'\t'<<c[0][1]<<'\t'<<c[1][0]<<'\t'<<c[1][1]<<endl;assert(!c[0][0]&&!c[0][1]);}}
// KQvKP -> KvKP (capture of queen by pawn side), only this material until target.
int id=ids[Q][P][1];auto&t=ts[id];vector<uint8_t> r(t.sz);vector<vector<U>> bins(128);for(U a=0;a<(U)t.sz;a++)if(t.v[a]==0&&ds[id][a]>0&&ds[id][a]!=INF)bins[ds[id][a]].push_back(a);long long c[2]={};for(int d=1;d<128;d++)for(U a:bins[d]){Pos p=dec(t,a);moves(t,p,[&](Move m,Pos v){auto[j,q]=child(t,p,m,v);U b=enc(ts[j],q);if(pc(ts[j].v[b])!=0||ds[j][b]!=d-1)return;if(j==id){if(r[b])r[a]=1;}else if(m.cap==2&&!m.pr)r[a]=1;});if(r[a])c[p.turn]++;}cout<<"KQvKP\tqueen_turn="<<c[0]<<"\tpawn_turn="<<c[1]<<endl;assert(c[0]==0);}
